import type { VariableConfig } from '../../Variable'

/**
 * Configuration type for yes/no variables
 */
export type YesNoVariableType<Type extends boolean = boolean> = VariableConfig<Type> & {
    /** Whether to validate the regex expression pattern */
    includeNone?: boolean
}

/**
 * A Variable for a yes/no field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the yes/no variable including:
 *   * **question** - Question text displayed to the user
 *   * **includeNone**? - Whether to include a "None" option
 *   * And all other properties from the base Variable type
 */
export function YesNoVariable(config: YesNoVariableType) {
    return config
}
